				+ "{ FILTER(EXISTS { FILTER(BOUND(?seed)) }) } UNION { FILTER(false) } }";
		List<Map<String, String>> expected = List.of();

		TupleExpr original = parse(query);
		assertThat(evaluate(original)).containsExactlyInAnyOrderElementsOf(expected);

		TupleExpr optimized = parse(query);
		Union union = findOnlyUnion(optimized);
